import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, texture, uv, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const cleanupTasks = [];
  const timelines = [];
  let disposed = false;
  let loadedTexture = null;

  root.userData.handlers = {};

  const width = 2.4;
  const height = 1.5;

  const panelGeometry = new PlaneGeometry(width, height, 1, 1);
  const gradientMaterial = new MeshBasicNodeMaterial();
  gradientMaterial.colorNode = mix(
    color('#0b0b10'),
    color('#16161d'),
    uv().y
  );

  const panel = new Mesh(panelGeometry, gradientMaterial);
  panel.position.z = -0.01;
  root.add(panel);

  const grainGeometry = new PlaneGeometry(width, height, 1, 1);
  const grainMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.14,
    depthWrite: false,
    color: '#e8ecf2'
  });

  const grain = new Mesh(grainGeometry, grainMaterial);
  grain.position.z = 0.012;
  root.add(grain);

  const accentGeometry = new PlaneGeometry(0.08, 0.56, 1, 1);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38'
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-0.92, 0, 0.035);
  root.add(accent);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left'
    });

    textObject.position.set(-0.78, -0.08, 0.045);
    root.add(textObject);
  }

  const billboardTarget = (renderer, scene, camera) => {
    root.quaternion.copy(camera.quaternion);
  };

  panel.onBeforeRender = billboardTarget;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (disposed) {
        tex.dispose?.();
        return;
      }

      loadedTexture = tex;
      tex.offset.set(0, 0);
      tex.repeat.set(1, 1);

      grainMaterial.map = texture(tex);
      grainMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const task of cleanupTasks) {
      task?.();
    }

    panelGeometry.dispose();
    grainGeometry.dispose();
    accentGeometry.dispose();

    gradientMaterial.dispose();
    grainMaterial.dispose();
    accentMaterial.dispose();

    loadedTexture?.dispose?.();
    root.clear();
  };

  return root;
}
